import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"^([0-9]{4,5})-[0-9]{4}$")
_TAG_SPLIT_RE = re.compile(r"[;,]")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _is_digits(s):
    return bool(s) and all("0" <= c <= "9" for c in s)


def _normalize_email(raw):
    s = raw.strip()
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _normalize_phone(raw):
    s = raw
    lowered = s.lower()
    cuts = [p for p in (lowered.find("x"), lowered.find("ext"), lowered.find("#")) if p != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if "0" <= c <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    z = raw.strip()
    m = _ZIP_PLUS4_RE.match(z)
    if m:
        z = m.group(1)
    if len(z) == 4 and _is_digits(z):
        z = "0" + z
    if len(z) == 5 and _is_digits(z):
        return z
    return ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw, row_index):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Row {row_index}: unrecognized 'updated' value {raw!r}")


def _parse_tags(raw):
    tags = set()
    for part in _TAG_SPLIT_RE.split(raw):
        t = part.strip().lower()
        if t:
            tags.add(t)
    return tags


def dedupe_contacts(rows):
    # Normalize each row; drop rows with neither a valid email nor a valid phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone", ""))
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": row.get("source", "").strip().lower(),
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row.get("updated", ""), idx),
        })

    # Union-find so that matching is transitive.
    n = len(recs)
    parent = list(range(n))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(i, first_by_email[r["email"]])
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in first_by_phone_last:
                union(i, first_by_phone_last[key])
            else:
                first_by_phone_last[key] = i

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)
    # Each member list is already in input order, so members[0] is the earliest row.
    ordered = sorted(groups.values(), key=lambda members: members[0])

    def pick(members, field):
        cands = [recs[i] for i in members if recs[i][field]]
        if not cands:
            return ""
        # Prefer manual sources, then the most recent updated, then the earlier input row.
        best = min(cands, key=lambda r: (r["source"] != "manual",
                                         datetime.max - r["updated"],
                                         r["idx"]))
        return best[field]

    result = []
    for members in ordered:
        group = [recs[i] for i in members]
        tags = set()
        for r in group:
            tags |= r["tags"]
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
        })
    return result
```

Notes:

- **Opt-outs are flagged, not removed.** Each output record has `opted_out` set to "Y" or "N". Filter to `opted_out == "N"` before building the send list, since a person with any opted-out row is marked "Y".
- **Bad `updated` values raise `ValueError`.** A value that matches none of the three formats stops the run and reports the row index, rather than being silently sorted to the wrong place.
- **ZIP+4 with a 4-digit prefix is handled.** A value like "2139-4307" (Excel dropped the leading zero) is read as ZIP+4, padded to "02139".
